INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'animation', 'n.', '/ˌænɪˈmeɪʃn/', '动画制作;动画片', 'Chinese ink wash animation turns paintings into moving art.', '中国水墨动画把绘画变成了会动的艺术。', 'Art', 1, 0, 'senior', 'wordlist', 'elective3', 'U1', 'ink wash animation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'arch', 'n./v.', '/ɑːtʃ/', '拱;拱门;(使)成弓形', 'Monet often painted the arch of the bridge in his garden.', '莫奈常画他花园里那座桥的拱形。', 'Art', 2, 0, 'senior', 'wordlist', 'elective3', 'U1', 'an arched bridge', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'artistic', 'adj.', '/ɑːˈtɪstɪk/', '艺术的;有艺术天赋的', 'The exhibition shows the artistic genius of ancient China.', '这次展览展示了古代中国的艺术天才。', 'Art', 3, 0, 'senior', 'wordlist', 'elective3', 'U1', 'artistic genius', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'ceramic', 'n./adj.', '/səˈræmɪk/', '陶瓷制品;制陶艺术;陶瓷的', 'Beautiful ceramic vases were on display in the museum.', '博物馆里展出着精美的陶瓷花瓶。', 'Art', 4, 0, 'senior', 'wordlist', 'elective3', 'U1', 'ceramic vases', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'civil', 'adj.', '/ˈsɪvl/', '国民的;民用的;民事的', 'Tang Yin failed to gain entry into the civil service and turned to painting.', '唐寅未能进入文官系统,转而从事绘画。', 'Art', 5, 0, 'senior', 'wordlist', 'elective3', 'U1', 'the civil service', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'client', 'n.', '/ˈklaɪənt/', '委托人;客户;顾客', 'A good artist builds trust with every client.', '优秀的艺术家会与每位客户建立信任。', 'Art', 6, 0, 'senior', 'wordlist', 'elective3', 'U1', 'trust with a client', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'contemporary', 'adj./n.', '/kənˈtemprəri/', '当代的;现代的;同时期的;同代人', 'Contemporary art by young painters is also worthy of attention.', '年轻画家创作的当代艺术也值得关注。', 'Art', 7, 0, 'senior', 'wordlist', 'elective3', 'U1', 'contemporary art', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'convey', 'v.', '/kənˈveɪ/', '表达;传递;传送', 'Monet''s aim was to convey the light and movement in the scene.', '莫奈的目标是表现场景中的光与动感。', 'Art', 8, 0, 'senior', 'wordlist', 'elective3', 'U1', 'convey a feeling', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'criticise', 'v.', '/ˈkrɪtɪsaɪz/', '批评;指责;评价', 'A humble person finds it hard to criticise other people''s work.', '谦逊的人很难去指责别人的作品。', 'Art', 9, 0, 'senior', 'wordlist', 'elective3', 'U1', 'criticise a painting', '美式拼 criticize;美音 /ˈkrɪtɪsaɪz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'criticism', 'n.', '/ˈkrɪtɪsɪzəm/', '批评;评论;评价', 'Honest art criticism can help an artist improve.', '诚恳的艺术评论能帮助艺术家进步。', 'Art', 10, 0, 'senior', 'wordlist', 'elective3', 'U1', 'art criticism', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'decline', 'n./v.', '/dɪˈklaɪn/', '减少;下降;衰落;谢绝', 'The speaker explained the decline in ink wash animation.', '演讲者解释了水墨动画的衰落。', 'Art', 11, 0, 'senior', 'wordlist', 'elective3', 'U1', 'the decline of a style', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dimension', 'n.', '/daɪˈmenʃn/', '维(度);规模;范围', 'Unlike painting, sculpture operates in three dimensions.', '与绘画不同,雕塑存在于三维空间中。', 'Art', 12, 0, 'senior', 'wordlist', 'elective3', 'U1', 'three dimensions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'two-dimensional', 'adj.', '/ˌtuː daɪˈmenʃənl/', '二维的;平面的', 'A painting on paper is a two-dimensional image.', '纸上的画是一种二维的图像。', 'Art', 13, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a two-dimensional image', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'emerge', 'v.', '/iˈmɜːdʒ/', '出现;浮现;兴起', 'Impressionism emerged in France in the late 19th century.', '印象主义于19世纪晚期在法国兴起。', 'Art', 14, 0, 'senior', 'wordlist', 'elective3', 'U1', 'emerge in France', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'entry', 'n.', '/ˈentri/', '进入;加入;参与(权)', 'He tried to gain entry into the civil service but failed.', '他试图进入文官系统但失败了。', 'Art', 15, 0, 'senior', 'wordlist', 'elective3', 'U1', 'gain entry into', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'exhibition', 'n.', '/ˌeksɪˈbɪʃn/', '展览;展览会', 'The museum''s new exhibition runs until November.', '博物馆的新展览将持续到十一月。', 'Art', 16, 0, 'senior', 'wordlist', 'elective3', 'U1', 'hold an exhibition', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'expansion', 'n.', '/ɪkˈspænʃn/', '扩张;扩展;扩大', 'Buddhist art did not begin to show expansion until the seventh century.', '佛教艺术直到七世纪才开始扩展。', 'Art', 17, 0, 'senior', 'wordlist', 'elective3', 'U1', 'show expansion', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fine art', 'n.', '/ˌfaɪn ˈɑːt/', '美术(尤指绘画和雕塑)', 'The Richfield Museum of Fine Art is proud of its new show.', '里奇菲尔德美术博物馆为其新展览感到自豪。', 'Art', 18, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a museum of fine art', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fond', 'adj.', '/fɒnd/', '喜爱的;深情的', 'Which period of Western art are you most fond of?', '你最喜爱西方艺术的哪个时期?', 'Art', 19, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be fond of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'frame', 'n./v.', '/freɪm/', '画面;框架;给……镶框', 'An animation film is drawn frame by frame.', '动画片是一帧一帧地画出来的。', 'Art', 20, 0, 'senior', 'wordlist', 'elective3', 'U1', 'frame by frame', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'guarantee', 'v./n.', '/ˌɡærənˈtiː/', '保证;确保;担保', 'No one can guarantee that an artist will become famous.', '没有人能保证一位艺术家会成名。', 'Art', 21, 0, 'senior', 'wordlist', 'elective3', 'U1', 'guarantee success', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'humanity', 'n.', '/hjuˈmænəti/', '人性;人道;(统称)人类', 'Renoir tried to show the inner warmth and humanity of his subjects.', '雷诺阿努力表现画中人物内在的温暖与人性。', 'Art', 22, 0, 'senior', 'wordlist', 'elective3', 'U1', 'inner humanity', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'humble', 'adj.', '/ˈhʌmbl/', '谦逊的;虚心的;卑微的', 'For a humble person, it is hard to praise themselves.', '对谦逊的人来说,自我夸赞是很难的。', 'Art', 23, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a humble person', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'in particular', 'phr.', '/ɪn pəˈtɪkjələ(r)/', '尤其;特别', 'Monet, in particular, loved painting the water lilies in his pond.', '莫奈尤其喜爱画他池塘里的睡莲。', 'Art', 24, 0, 'senior', 'wordlist', 'elective3', 'U1', 'in particular', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'influential', 'adj.', '/ˌɪnfluˈenʃl/', '有影响力的;有支配力的', 'Monet was one of the most influential Impressionist painters.', '莫奈是最有影响力的印象派画家之一。', 'Art', 25, 0, 'senior', 'wordlist', 'elective3', 'U1', 'an influential painter', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'ink', 'n.', '/ɪŋk/', '墨水;墨汁;油墨', 'Chinese ink wash painting uses water and black ink.', '中国水墨画使用水和黑墨。', 'Art', 26, 0, 'senior', 'wordlist', 'elective3', 'U1', 'ink wash painting', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'investment', 'n.', '/ɪnˈvestmənt/', '投资;投资额;(时间精力的)投入', 'An art collector should have realistic expectations of any investment.', '艺术收藏家对任何投资都应有现实的预期。', 'Art', 27, 0, 'senior', 'wordlist', 'elective3', 'U1', 'returns from investment', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'memorial', 'n./adj.', '/məˈmɔːriəl/', '纪念碑;纪念物;纪念的', 'The leaders'' aim was to build a memorial to the heroes.', '领导人的目标是为英雄们建造一座纪念碑。', 'Art', 28, 0, 'senior', 'wordlist', 'elective3', 'U1', 'build a memorial', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'mythology', 'n.', '/mɪˈθɒlədʒi/', '神话;神话学', 'Many old European paintings show scenes from mythology.', '许多古老的欧洲绘画描绘神话场景。', 'Art', 29, 0, 'senior', 'wordlist', 'elective3', 'U1', 'religious mythology', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'noble', 'adj./n.', '/ˈnəʊbl/', '崇高的;高贵的;贵族', 'The mother''s wish was to raise her son to have a noble mind.', '母亲的愿望是把儿子培养成有崇高心灵的人。', 'Art', 30, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a noble mind', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'outer', 'adj.', '/ˈaʊtə(r)/', '外部的;外边的;外围的', 'Renoir wanted to show more than just the outer image of people.', '雷诺阿想表现的不只是人物的外表形象。', 'Art', 31, 0, 'senior', 'wordlist', 'elective3', 'U1', 'the outer image', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'permanent', 'adj.', '/ˈpɜːmənənt/', '永久的;永恒的;长久的', 'The two leaders'' aim was to achieve permanent peace.', '两位领导人的目标是实现持久和平。', 'Art', 32, 0, 'senior', 'wordlist', 'elective3', 'U1', 'permanent peace', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'photography', 'n.', '/fəˈtɒɡrəfi/', '摄影;摄影术', 'After the invention of photography, painters looked at art in a new way.', '摄影术发明之后,画家们以新的方式看待艺术。', 'Art', 33, 0, 'senior', 'wordlist', 'elective3', 'U1', 'the invention of photography', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pond', 'n.', '/pɒnd/', '池塘;水池', 'Monet painted the water lilies floating on the pond.', '莫奈画了漂浮在池塘上的睡莲。', 'Art', 34, 0, 'senior', 'wordlist', 'elective3', 'U1', 'water lilies in the pond', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'precise', 'adj.', '/prɪˈsaɪs/', '准确的;精确的', 'Impressionists did not aim to make a precise record of a scene.', '印象派画家并不追求精确记录某个场景。', 'Art', 35, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a precise record', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'precisely', 'adv.', '/prɪˈsaɪsli/', '准确地;精确地;的确', 'Realist painters tried to paint things precisely as they looked.', '写实派画家力求把事物画得与实物完全一致。', 'Art', 36, 0, 'senior', 'wordlist', 'elective3', 'U1', 'paint precisely', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'primitive', 'adj.', '/ˈprɪmətɪv/', '原始的;远古的;发展水平低的', 'Some primitive art was carved on stone thousands of years ago.', '一些原始艺术是数千年前刻在石头上的。', 'Art', 37, 0, 'senior', 'wordlist', 'elective3', 'U1', 'primitive art', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'purchase', 'v./n.', '/ˈpɜːtʃəs/', '购买;采购;购买的东西', 'The first rule for any collector is to purchase only what you love.', '任何收藏家的首要原则是只买你真正喜爱的。', 'Art', 38, 0, 'senior', 'wordlist', 'elective3', 'U1', 'purchase a painting', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rank', 'n./v.', '/ræŋk/', '地位;级别;把……分等级', 'Tang Yin gained a high rank among Chinese artists.', '唐寅在中国艺术家中获得了崇高的地位。', 'Art', 39, 0, 'senior', 'wordlist', 'elective3', 'U1', 'high rank', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'realistic', 'adj.', '/ˌriːəˈlɪstɪk/', '逼真的;现实的', 'Earlier Realists painted in a very realistic style.', '早期的写实派画家以非常逼真的风格作画。', 'Art', 40, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a realistic style', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'realism', 'n.', '/ˈriːəlɪzəm/', '现实主义;逼真;务实', 'Realism in art tries to show life as it truly is.', '艺术中的现实主义力求表现生活的真实样貌。', 'Art', 41, 0, 'senior', 'wordlist', 'elective3', 'U1', 'the spirit of realism', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'recognition', 'n.', '/ˌrekəɡˈnɪʃn/', '承认;认可;赞誉', 'In time, Tang Yin gained recognition as a great artist.', '假以时日,唐寅获得了伟大艺术家的赞誉。', 'Art', 42, 0, 'senior', 'wordlist', 'elective3', 'U1', 'gain recognition', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'representative', 'adj./n.', '/ˌreprɪˈzentətɪv/', '典型的;有代表性的;代表', 'These three films are representative of ink wash animation.', '这三部影片是水墨动画的代表作。', 'Art', 43, 0, 'senior', 'wordlist', 'elective3', 'U1', 'representative works', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'reputation', 'n.', '/ˌrepjuˈteɪʃn/', '名誉;名声', 'A great painter slowly builds a reputation over many years.', '伟大的画家是在许多年里慢慢建立起名声的。', 'Art', 44, 0, 'senior', 'wordlist', 'elective3', 'U1', 'build a reputation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sculpture', 'n.', '/ˈskʌlptʃə(r)/', '雕像;雕刻品;雕刻术', 'Tang Dynasty sculpture was highly influenced by Buddhist art.', '唐代雕塑深受佛教艺术的影响。', 'Art', 45, 0, 'senior', 'wordlist', 'elective3', 'U1', 'Tang Dynasty sculpture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sculptor', 'n.', '/ˈskʌlptə(r)/', '雕刻家;雕塑家', 'The sculptor spent years carving a single stone figure.', '这位雕塑家花了数年雕刻一座石像。', 'Art', 46, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a famous sculptor', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'subjective', 'adj.', '/səbˈdʒektɪv/', '主观的', 'Monet painted the subjective impression a scene gave him.', '莫奈画的是场景给他的主观印象。', 'Art', 47, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a subjective impression', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'subsequent', 'adj.', '/ˈsʌbsɪkwənt/', '随后的;后来的;之后的', 'After Impressionism, subsequent artists asked what to do next.', '印象主义之后,后来的艺术家们思考接下来该做什么。', 'Art', 48, 0, 'senior', 'wordlist', 'elective3', 'U1', 'subsequent artists', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'symphony', 'n.', '/ˈsɪmfəni/', '交响乐;交响曲', 'The film''s music sounds like a gentle symphony.', '这部影片的音乐听起来像一首柔和的交响曲。', 'Art', 49, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a symphony of colour', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'vase', 'n.', '/vɑːz/', '花瓶;装饰瓶', 'A blue ceramic vase stood at the centre of the exhibition.', '一只蓝色的陶瓷花瓶摆在展览的中央。', 'Art', 50, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a ceramic vase', '美音 /veɪs/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'visual', 'adj.', '/ˈvɪʒuəl/', '视觉的;视力的', 'Monet was impressed by the visual effects of the steam engine.', '莫奈对蒸汽机车的视觉效果印象深刻。', 'Art', 51, 0, 'senior', 'wordlist', 'elective3', 'U1', 'visual effects', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'worthy', 'adj.', '/ˈwɜːði/', '值得的;有价值的', 'Contemporary art is also worthy of your attention.', '当代艺术也值得你的关注。', 'Art', 52, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be worthy of', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u1.01', '①be + to do 作表语(主语为 advice/dream/aim 等抽象名词)', 'A2', 12, '选择性必修三 U1 — 当主语是 advice/dream/aim/goal/wish/job 等抽象名词,系动词 be 后用动词不定式 to do 作表语,说明主语的具体内容。如 My advice is to start early.', 1, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u1.02', '②疑问词 + to do 作表语(what/how/where/whether + to do)', 'A2', 12, '选择性必修三 U1 — 当主语为 question/problem/point 等、其内容是一个''做什么/怎么做''的问题时,be 后用''疑问词 + 不定式''作表语。如 The question is what to paint next.', 2, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u1.03', '③be to do 表计划/职责/将来 与 doing(动名词表语)的对照', 'A2', 12, '选择性必修三 U1 — 主语为 plan/task/duty/aim 等表''计划·职责·将来''时,be 后用 to do;但主语为 hobby/interest/job(指日常所做之事)说明''是什么活动''时,用动名词 doing 作表语。看主语含义选形式。', 3, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'If you want to learn how to paint, my advice is ____ a famous artist''s work first.', 'to copy', 'copying', 'copied', 'copy', 'A', '主语 advice 是抽象名词,be 后用不定式作表语 → to copy。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'Her dream is ____ a great Impressionist painter one day.', 'becoming', 'to become', 'become', 'became', 'B', '主语 dream 后 be + 不定式作表语 → to become。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'Monet''s aim was ____ the light and movement in the scene.', 'conveying', 'conveyed', 'to convey', 'convey', 'C', '主语 aim,be 后接不定式作表语 → to convey。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The best way to understand Western art is ____ how its painting changed over time.', 'looking at', 'looked at', 'look at', 'to look at', 'D', '主语含 way,be 后用不定式作表语 → to look at。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The mother''s wish was ____ her son into a man with a noble mind.', 'to raise', 'raising', 'raised', 'raise', 'A', '主语 wish,be 后不定式作表语 → to raise。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The museum''s goal is ____ the artistic genius of ancient China.', 'displaying', 'to display', 'displayed', 'display', 'B', '主语 goal,be 后不定式作表语 → to display。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The first rule for any art collector is ____ only what you truly love.', 'purchasing', 'purchased', 'to purchase', 'purchase', 'C', '主语 rule,be 后不定式作表语 → to purchase。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The young singer''s intention was ____ his love for rock music with his fans.', 'sharing', 'shared', 'share', 'to share', 'D', '主语 intention,be 后不定式作表语 → to share。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The aim of the two leaders was ____ permanent peace between their countries.', 'to achieve', 'achieving', 'achieved', 'achieve', 'A', '主语 aim,be 后不定式作表语 → to achieve。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The purpose of art education is ____ students to be creative.', 'inspiring', 'to inspire', 'inspired', 'inspire', 'B', '主语 purpose,be 后不定式作表语 → to inspire。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'My suggestion is ____ to your own inner voice before you start a painting.', 'listening', 'listened', 'to listen', 'listen', 'C', '主语 suggestion,be 后不定式作表语 → to listen。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'His one hope after the long exhibition was simply ____ alone for a while.', 'being left', 'been left', 'be left', 'to be left', 'D', '主语 hope,be 后不定式作表语(被动)→ to be left。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The best way to do business with people is ____ trust with every client.', 'to build', 'building', 'built', 'build', 'A', '主语含 way,be 后不定式作表语 → to build。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'Renoir''s aim was ____ not just the outer image but the inner warmth of people.', 'showing', 'to show', 'shown', 'show', 'B', '主语 aim,be 后不定式作表语 → to show。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'One reason for the exhibition is ____ visitors to ancient Chinese art.', 'introducing', 'introduced', 'to introduce', 'introduce', 'C', '主语 reason 在此后 be + 不定式作表语 → to introduce。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'My ideal job is ____ beautiful ceramic vases by hand.', 'making', 'made', 'make', 'to make', 'D', '主语 job 此处指目标,be 后不定式作表语 → to make。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'A humble artist''s wish is never ____ other people''s honest work.', 'to criticise', 'criticising', 'criticised', 'criticise', 'A', '主语 wish,be 后不定式作表语 → to criticise。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The leaders'' aim was ____ a memorial to the heroes who saved the city.', 'building', 'to build', 'built', 'build', 'B', '主语 aim,be 后不定式作表语 → to build。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'The least you could do now is ____ a single character with the brush.', 'practising', 'practised', 'to practise', 'practise', 'C', '主语 the least,be 后不定式作表语 → to practise。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.01'), 'What I want to do this weekend is ____ the new art exhibition in town.', 'visiting', 'visited', 'visit', 'to visit', 'D', '主语为 what 引导的从句,be 后不定式作表语 → to visit。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'The question for many young painters is ____ next.', 'what to paint', 'what painting', 'what painted', 'what paint', 'A', '主语 question,内容是''画什么'',be 后用''疑问词+不定式''作表语 → what to paint。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'When you face a blank canvas, the problem is ____.', 'how beginning', 'how to begin', 'how begun', 'how begin', 'B', '主语 problem,内容是''如何开始'',be 后用''how + 不定式'' → how to begin。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'For a new collector, the first question is ____ in the first place.', 'what buying', 'what bought', 'what to buy', 'what buy', 'C', 'be 后用''what + 不定式''作表语 → what to buy。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'The real difficulty is ____ the mood of the scene with so few colours.', 'how conveying', 'how conveyed', 'how convey', 'how to convey', 'D', '主语 difficulty,内容是''如何表达'',用''how + 不定式'' → how to convey。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'Before the trip, the question was ____ to see the famous sculptures.', 'where to go', 'where going', 'where gone', 'where go', 'A', 'be 后用''where + 不定式''作表语 → where to go。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'His main worry was ____ the old painting without harming it.', 'how cleaning', 'how to clean', 'how cleaned', 'how clean', 'B', '主语 worry,用''how + 不定式''作表语 → how to clean。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'For the guide, the only question was ____ first in such a huge museum.', 'which room entering', 'which room entered', 'which room to enter', 'which room enter', 'C', 'be 后用''which + 名词 + 不定式''作表语 → which room to enter。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'The hardest part of the project is ____ when to stop adding colour.', 'deciding', 'decided', 'decide', 'to decide', 'D', '主语 part,be 后不定式作表语 → to decide。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'For the museum, the challenge is ____ such old vases safely.', 'how to store', 'how storing', 'how stored', 'how store', 'A', '用''how + 不定式''作表语 → how to store。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'Now the only question is ____ the exhibition this year or not.', 'whether holding', 'whether to hold', 'whether held', 'whether hold', 'B', 'be 后用''whether + 不定式''作表语 → whether to hold。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'For a beginner, the problem is often ____ a soft brush correctly.', 'how holding', 'how held', 'how to hold', 'how hold', 'C', '主语 problem,用''how + 不定式'' → how to hold。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'The teacher''s question was ____ each painting to its correct period.', 'how matching', 'how matched', 'how match', 'how to match', 'D', '用''how + 不定式''作表语 → how to match。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'For the young artist, the question was ____ a realistic or an abstract style.', 'whether to choose', 'whether choosing', 'whether chosen', 'whether choose', 'A', 'be 后用''whether + 不定式''作表语 → whether to choose。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'The point of the lesson is ____ the difference between the two art forms.', 'explaining', 'to explain', 'explained', 'explain', 'B', '主语 point,be 后不定式作表语 → to explain。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'Standing before the huge scroll, my first question was ____ looking.', 'where starting', 'where started', 'where to start', 'where start', 'C', '用''where + 不定式''作表语 → where to start。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'For the curator, the question is ____ the new bronze pieces this autumn.', 'when showing', 'when shown', 'when show', 'when to show', 'D', '用''when + 不定式''作表语 → when to show。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'The problem now is ____ light and movement using only quick brushstrokes.', 'how to capture', 'how capturing', 'how captured', 'how capture', 'A', '用''how + 不定式''作表语 → how to capture。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'Before the talk show, the host''s question was ____ the guest artist first.', 'what asking', 'what to ask', 'what asked', 'what ask', 'B', '用''what + 不定式''作表语 → what to ask。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'For the gallery owner, the question was ____ the painting at such a price.', 'whether purchasing', 'whether purchased', 'whether to purchase', 'whether purchase', 'C', '用''whether + 不定式''作表语 → whether to purchase。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.02'), 'The big question for the class was ____ the difference between the two styles.', 'how telling', 'how told', 'how tell', 'how to tell', 'D', '用''how + 不定式''作表语 → how to tell。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The museum''s plan for next spring is ____ a special exhibition of Tang Dynasty sculpture.', 'to hold', 'holding', 'held', 'hold', 'A', '主语 plan 表将来计划,be 后用不定式作表语 → to hold。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'His favourite hobby is ____ the water lilies in the pond every morning.', 'to have painted', 'painting', 'painted', 'paint', 'B', '主语 hobby 指日常所做的活动,be 后用动名词作表语 → painting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The artist''s task this month is ____ the old wall painting back to life.', 'bringing', 'brought', 'to bring', 'bring', 'C', '主语 task 表职责,be 后用不定式作表语 → to bring。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'Grandpa''s chief interest is ____ Chinese calligraphy with an old soft brush.', 'to be practised', 'practised', 'practise', 'practising', 'D', '主语 interest 指日常爱好活动,be 后用动名词作表语 → practising。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The duty of the night guard is ____ over the priceless ceramic vases.', 'to watch', 'watching', 'watched', 'watch', 'A', '主语 duty 表职责,be 后用不定式作表语 → to watch。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'What the survivors attempted to do was no longer ____ reality, but to ask a question.', 'showing', 'to show', 'shown', 'show', 'B', '主语为 what 从句,be 后不定式作表语(与后面 to ask 并列)→ to show。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'Her weekend pleasure is ____ around the city''s small art galleries.', 'to have walked', 'walked', 'walking', 'walk', 'C', '主语 pleasure 指日常享受的活动,be 后用动名词作表语 → walking。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The committee''s aim for this year is ____ young artists a chance to show their work.', 'giving', 'given', 'give', 'to give', 'D', '主语 aim 表目标,be 后用不定式作表语 → to give。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'His lifelong job is ____ broken sculptures so that they look new again.', 'to repair', 'repairing', 'repaired', 'repair', 'A', '主语 job 此处说明其职责,be 后用不定式作表语 → to repair。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The old painter''s quiet joy is ____ ink slowly across the white paper.', 'to be spread', 'spreading', 'spread', 'to have spread', 'B', '主语 joy 指日常进行的活动,be 后用动名词作表语 → spreading。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The school''s plan is ____ a famous sculptor to give a talk next week.', 'inviting', 'invited', 'to invite', 'invite', 'C', '主语 plan 表将来计划,be 后用不定式作表语 → to invite。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'My favourite pastime is ____ ink wash animation films at the weekend.', 'to be watched', 'watched', 'to have watched', 'watching', 'D', '主语 pastime 指日常消遣活动,be 后用动名词作表语 → watching。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The next task for the team is ____ the painting to another quiet room.', 'to move', 'moving', 'moved', 'move', 'A', '主语 task 表职责,be 后用不定式作表语 → to move。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'Her main hobby these days is ____ small clay figures of animals.', 'to be made', 'making', 'made', 'to have made', 'B', '主语 hobby 指日常活动,be 后用动名词作表语 → making。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The plan of the art club is ____ to the museum together on Sunday.', 'travelling', 'travelled', 'to travel', 'travel', 'C', '主语 plan 表将来安排,be 后用不定式作表语 → to travel。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'His one bad habit is ____ his own work far too harshly.', 'to be criticised', 'criticised', 'to have criticised', 'criticising', 'D', '主语 habit 指日常反复所做之事,be 后用动名词作表语 → criticising。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The aim of the project is ____ the long story of Chinese art to young visitors.', 'to tell', 'telling', 'told', 'tell', 'A', '主语 aim 表目标,be 后用不定式作表语 → to tell。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The artist''s daily routine is ____ before sunrise to catch the best light.', 'to be got up', 'getting up', 'got up', 'to have got up', 'B', '主语 routine 指日常习惯活动,be 后用动名词作表语 → getting up。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The gallery''s plan for the summer is ____ more contemporary works on show.', 'putting', 'put', 'to put', 'to have put', 'C', '主语 plan 表将来计划,be 后用不定式作表语 → to put。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U1' AND code='e3u1.03'), 'The whole point of the new policy is ____ free entry to every student.', 'offering', 'offered', 'offer', 'to offer', 'D', '主语 point 表目的,be 后用不定式作表语 → to offer。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'How Photography Changed Painting', 'For a long time, the main job of Western painters was to record what people and the world looked like. They tried to paint things as precisely as a mirror. Then, in the middle of the 19th century, photography was invented. Suddenly a camera could capture a face or a street far more exactly than any brush. After that, paintings were no longer needed simply to preserve how things looked. So painters had to find a new way of looking at their art. From this fresh thinking, Impressionism emerged in France. Instead of copying every detail, Impressionist painters tried to catch light, colour, and movement, and the feeling a scene gave them at a single moment. In other words, the camera did not kill painting. It set painters free to do something a machine could never do, which was to share their own way of seeing the world.', 'Art', 148, '[{"q":"What was the main job of Western painters before photography?","answer":"A","options":["To make a faithful record of how things looked.","To invent new cameras.","To paint only their own feelings.","To copy Chinese ink paintings."],"explanation":"原文 ''the main job… was to record what people and the world looked like'' 的转述。"},{"q":"How did the camera affect painters, according to the text?","answer":"B","options":["It made them stop painting forever.","It freed them to paint in a new way.","It forced them to copy more details.","It was useless to them."],"explanation":"末段 ''It set painters free to do something a machine could never do'' 的转述。"},{"q":"What did Impressionist painters mainly try to capture?","answer":"A","options":["Light, colour and a moment''s feeling.","Every tiny detail of a face.","The exact price of a scene.","Old religious stories."],"explanation":"原文 ''tried to catch light, colour, and movement, and the feeling a scene gave them'' 的转述。"}]'::jsonb, '[{"word":"photography","cn":"摄影术"},{"word":"precisely","cn":"精确地"},{"word":"emerge","cn":"兴起;出现"}]'::jsonb, 2, 'elective3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Monet and the Garden at Giverny', 'Claude Monet was one of the most influential Impressionist painters. The new movement even took its name from his work called Impression, Sunrise. In that painting, his aim was not to make a precise record of the harbour, but to convey the subjective impression the scene gave him at dawn. Later in life, Monet moved with his large family to a village called Giverny. There he purchased a house and some land, and built a beautiful garden with a pond, water lilies, and an arched bridge. During his days at Giverny, Monet painted his own garden again and again. Two things appeared in his work throughout this period: bright colours, and the reflections of light in the water. He was so fond of his lilies that he returned to them for almost thirty years. Through these quiet garden scenes, Monet showed the world how much beauty can be found in one small, familiar place.', 'Art', 154, '[{"q":"Where did the name of Impressionism come from?","answer":"B","options":["The village of Giverny.","A painting by Monet.","A French newspaper.","A type of camera."],"explanation":"原文 ''the new movement even took its name from his work called Impression, Sunrise'' 的转述。"},{"q":"What did Monet do after moving to Giverny?","answer":"C","options":["He gave up painting.","He only painted the sea.","He created a garden and painted it many times.","He sold all his lilies."],"explanation":"原文 ''built a beautiful garden… painted his own garden again and again'' 的转述。"},{"q":"What two things often appeared in his Giverny paintings?","answer":"D","options":["Trains and stations.","Black-and-white photographs.","Snow and high mountains.","Bright colours and reflections in water."],"explanation":"原文 ''bright colours, and the reflections of light in the water'' 的转述。"}]'::jsonb, '[{"word":"influential","cn":"有影响力的"},{"word":"subjective","cn":"主观的"},{"word":"purchase","cn":"购买"}]'::jsonb, 2, 'elective3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Beauty of Chinese Ink Wash', 'Chinese ink wash painting is a very old and special art form. Unlike many Western paintings, which are full of strong colours, ink wash uses mainly water and black ink on paper. By controlling how wet or dry the brush is, a painter can create soft greys as well as deep blacks. With just a few lines, a skilled artist can suggest a whole mountain, a river, or a bird in flight. The aim is not to copy nature exactly, but to capture its spirit and leave room for the viewer''s imagination. Often a large part of the paper is simply left empty, and that empty space is as important as the ink itself. This tradition later gave birth to ink wash animation films, in which the gentle paintings seem to move and breathe. To many people, these films are among the most beautiful examples of how ancient Chinese art can find new life in a modern form.', 'Art', 158, '[{"q":"How is ink wash painting different from many Western paintings?","answer":"A","options":["It mainly uses water and black ink instead of strong colours.","It can only be done by foreigners.","It uses no brush at all.","It always copies nature exactly."],"explanation":"原文 ''ink wash uses mainly water and black ink… full of strong colours'' 的转述。"},{"q":"Why is the empty space important in ink wash painting?","answer":"B","options":["It saves expensive ink.","It matters as much as the painted parts.","It hides the artist''s mistakes.","It has no real meaning."],"explanation":"原文 ''that empty space is as important as the ink itself'' 的转述。"},{"q":"What does the writer say about ink wash animation films?","answer":"C","options":["They are boring and old-fashioned.","They have replaced all Western films.","They give an ancient art a new life.","They use only Western music."],"explanation":"末段 ''how ancient Chinese art can find new life in a modern form'' 的转述。"}]'::jsonb, '[{"word":"ink","cn":"墨"},{"word":"animation","cn":"动画"}]'::jsonb, 2, 'elective3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'A Visit to the Museum of Fine Art', 'Last Sunday our art club visited a new show at the Museum of Fine Art. Its title was Chinese Art Through the Ages, and it covered more than three thousand years. As soon as we entered, we saw bronze bowls and ceramic vases shining under soft lights. The highlight was an old painting by Tang Yin, a master who was born during the Ming Dynasty. He had once tried to enter the civil service but failed, so he turned to painting instead, and in time he gained recognition as one of China''s greatest artists. His snowy mountain scene looked as fresh as the day it was made, though it was over five hundred years old. We also saw many Tang Dynasty sculptures, most of them of Buddhist origin, brought to China along the Silk Road. By the end of the visit, we all agreed that the show had carried us back through the long, rich story of Chinese art.', 'Art', 159, '[{"q":"What did the visitors see first when they entered the show?","answer":"D","options":["A modern oil painting.","A short film about France.","An empty white room.","Shining bronze and ceramic objects."],"explanation":"原文 ''we saw bronze bowls and ceramic vases shining under soft lights'' 的转述(改写非照抄)。"},{"q":"Why did Tang Yin turn to painting?","answer":"A","options":["He had not managed to join the civil service.","He disliked all officials.","He was told to by an emperor.","He wanted to become rich quickly."],"explanation":"原文 ''tried to enter the civil service but failed, so he turned to painting'' 的转述。"},{"q":"Where did most of the Tang Dynasty sculptures come from in spirit?","answer":"B","options":["From Western Europe.","From Buddhist art along the Silk Road.","From modern factories.","From the museum''s own workshop."],"explanation":"原文 ''most of them of Buddhist origin, brought to China along the Silk Road'' 的转述。"}]'::jsonb, '[{"word":"ceramic","cn":"陶瓷的"},{"word":"recognition","cn":"认可;赞誉"},{"word":"sculpture","cn":"雕塑"}]'::jsonb, 2, 'elective3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'What Comes After Impressionism', 'After Impressionism, a group of subsequent artists began to ask a new question: what should we do next? They felt that simply showing light and colour was no longer enough. Some, like Picasso, tried to break objects into shapes and put them together again in a strange new way. Others gave their paintings a realistic but dream-like quality, so that a scene looked both true and impossible at the same time. Still others turned away from the real world completely and painted only shapes and colours that stood for nothing at all. What linked these very different artists was one bold idea. Their aim was no longer to show reality, but instead to ask the big question, ''What is art?'' Because of them, modern art became a place for experiment, where almost any idea could be tried. Today, when we stand puzzled in front of a strange modern painting, we are really being invited to think about that same question for ourselves.', 'Art', 162, '[{"q":"What question did artists after Impressionism begin to ask?","answer":"C","options":["What art should do and be next.","How to copy photographs better.","Where to buy cheaper paint.","When to stop painting forever."],"explanation":"原文 ''what should we do next?'' 与 ''ask the big question, What is art?'' 的转述。"},{"q":"How did some artists like Picasso change painting?","answer":"D","options":["They copied nature even more closely.","They used only black ink.","They stopped using any colour.","They broke objects into shapes and rebuilt them."],"explanation":"原文 ''break objects into shapes and put them together again in a strange new way'' 的转述。"},{"q":"What did these different modern artists have in common?","answer":"A","options":["They shared one bold idea about questioning art.","They all painted the same garden.","They all hated colour.","They all lived in China."],"explanation":"原文 ''What linked these very different artists was one bold idea'' 的转述。"}]'::jsonb, '[{"word":"subsequent","cn":"随后的"},{"word":"realistic","cn":"逼真的"}]'::jsonb, 2, 'elective3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Renoir: Painter of Warmth', 'While many Impressionists loved to paint nature or daily street life, Renoir chose people as his favourite subject. He was born in France in the 1840s and became known for the warmth that fills his pictures. The photographs of his time were cold and black-and-white, but Renoir''s paintings are full of soft light, shadow, colour, and life. When he painted a friend or a child, he did not stop at the outer image of the face. Instead, he tried to show the inner warmth and humanity of the person behind it. People in his work often seem to be smiling gently, as if caught in a happy moment that will never end. Renoir once said that there was already enough that was sad in the world, so a painting should be a thing of joy and beauty. Even today, standing before his canvases, viewers feel as if they have stepped into a kinder, sunnier world.', 'Art', 155, '[{"q":"What did Renoir most like to paint?","answer":"B","options":["Trains.","People.","Empty rooms.","High mountains."],"explanation":"原文 ''Renoir chose people as his favourite subject'' 的转述。"},{"q":"How are Renoir''s paintings different from the photos of his time?","answer":"C","options":["They are smaller in size.","They use no people at all.","They are warm and full of light and colour.","They were made by a machine."],"explanation":"原文 ''photographs… were cold and black-and-white, but Renoir''s paintings are full of soft light… and life'' 的转述。"},{"q":"What did Renoir believe a painting should be?","answer":"D","options":["A copy of a photograph.","A record of sad events.","A list of prices.","Something joyful and beautiful."],"explanation":"原文 ''a painting should be a thing of joy and beauty'' 的转述(改写非照抄)。"}]'::jsonb, '[{"word":"humanity","cn":"人性"},{"word":"outer","cn":"外部的"}]'::jsonb, 2, 'elective3', 'U1');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U1', 'My First Art Show', 'Last month our class held a small art (1)____ in the school hall. For weeks, my biggest (2)____ had been how to begin my own painting. My teacher told me that the best way to start was simply (3)____ what I loved. So I chose to paint the old (4)____ bridge over the river near my home. At first my lines were shaky, and I almost wanted to give (5)____. But step by step, I learned to (6)____ the soft light on the water. When visitors looked at my work, some of them gently (7)____ it, and their honest words helped me a lot. By the end of the day, I felt very (8)____ of what I had made. That show taught me that art is not about being perfect; it is about (9)____ how you see the world. Now my plan is to keep (10)____ every single day.', 149, 2, '[{"q":"1","answer":"A","options":["exhibition","machine","market","garden"],"explanation":"art exhibition 艺术展。"},{"q":"2","answer":"B","options":["price","problem","noise","weather"],"explanation":"my biggest problem 最大的难题。"},{"q":"3","answer":"C","options":["to sell","to throw","to paint","to lose"],"explanation":"to paint what I loved 画我喜爱的。"},{"q":"4","answer":"D","options":["empty","broken","silent","arched"],"explanation":"arched bridge 拱桥。"},{"q":"5","answer":"A","options":["up","in","off","out"],"explanation":"give up 放弃。"},{"q":"6","answer":"B","options":["sell","convey","hide","forget"],"explanation":"convey the soft light 表现柔和的光。"},{"q":"7","answer":"C","options":["ate","sold","criticised","lost"],"explanation":"criticised it 评论它。"},{"q":"8","answer":"D","options":["afraid","angry","bored","proud"],"explanation":"proud of 为……自豪。"},{"q":"9","answer":"A","options":["sharing","selling","hiding","wasting"],"explanation":"sharing how you see 分享你的看法。"},{"q":"10","answer":"B","options":["sleeping","painting","shopping","running"],"explanation":"keep painting 坚持画画。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U1', 'Learning Ink Wash Painting', 'My grandfather is the person who first showed me Chinese (1)____ wash painting. He told me it is an old art (2)____ done with water and black ink. At first my brush felt strange in my (3)____, and every line came out wrong. Grandpa said that the secret was to (4)____ how wet or dry the brush should be. He also reminded me to leave part of the paper (5)____, because empty space is part of the picture. Little by little, I learned to (6)____ a mountain with only a few simple lines. Now this gentle art is the (7)____ I enjoy most after school. It makes me feel calm and (8)____ me to a long tradition. Whenever I pick up my brush, I feel (9)____ to be part of such an ancient art. My grandfather smiles and says that one day I may even paint better (10)____ him.', 149, 2, '[{"q":"1","answer":"C","options":["milk","oil","ink","soup"],"explanation":"ink wash painting 水墨画。"},{"q":"2","answer":"D","options":["price","shop","noise","form"],"explanation":"art form 艺术形式。"},{"q":"3","answer":"A","options":["hand","box","car","bag"],"explanation":"in my hand 在手里。"},{"q":"4","answer":"B","options":["sell","control","throw","lose"],"explanation":"control how wet 控制干湿。"},{"q":"5","answer":"C","options":["wet","loud","empty","rich"],"explanation":"leave part empty 留白。"},{"q":"6","answer":"D","options":["eat","buy","drop","suggest"],"explanation":"suggest a mountain 暗示出一座山。"},{"q":"7","answer":"A","options":["hobby","price","city","machine"],"explanation":"the hobby I enjoy 爱好。"},{"q":"8","answer":"B","options":["sells","connects","breaks","loses"],"explanation":"connects me to 把我和……相连。"},{"q":"9","answer":"C","options":["afraid","sorry","proud","bored"],"explanation":"proud to be part 自豪。"},{"q":"10","answer":"D","options":["under","after","behind","than"],"explanation":"better than 比……更好。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U1', 'A Day at the Museum', 'On Saturday my friend and I spent a whole day at the city (1)____ of fine art. There was so much to see that our first (2)____ was simply where to start. We decided to (3)____ with the ancient room. Inside, beautiful ceramic (4)____ stood quietly behind the glass, each one hundreds of years old. A guide explained that some of them were once owned by an (5)____. In the next room, we found a snowy mountain painting that looked as (6)____ as the day it was made. Later we saw many stone (7)____ of the Tang Dynasty, most of them with a peaceful smile on their faces. I was (8)____ by how skilful the old artists were. By the time the museum (9)____, my head was full of pictures and stories. On the way home, I told my friend that the visit had (10)____ us back through thousands of years of art.', 153, 2, '[{"q":"1","answer":"A","options":["museum","garden","factory","station"],"explanation":"museum of fine art 美术博物馆。"},{"q":"2","answer":"B","options":["price","question","song","meal"],"explanation":"first question 第一个问题。"},{"q":"3","answer":"C","options":["sleep","cry","begin","leave"],"explanation":"begin with 从……开始。"},{"q":"4","answer":"D","options":["coins","songs","trains","vases"],"explanation":"ceramic vases 陶瓷花瓶。"},{"q":"5","answer":"A","options":["emperor","error","engine","evening"],"explanation":"owned by an emperor 皇帝拥有。"},{"q":"6","answer":"B","options":["loud","fresh","empty","cheap"],"explanation":"as fresh as 像……一样新。"},{"q":"7","answer":"C","options":["prices","noises","sculptures","tickets"],"explanation":"stone sculptures 石雕。"},{"q":"8","answer":"D","options":["bored","angry","afraid","amazed"],"explanation":"amazed by 被……惊到。"},{"q":"9","answer":"A","options":["closed","ate","sold","ran"],"explanation":"the museum closed 闭馆。"},{"q":"10","answer":"B","options":["thrown","carried","broken","lost"],"explanation":"carried us back 带我们回到。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U1', 'Advice from an Art Collector', 'My uncle has collected paintings for many years, and he often gives me useful (1)____. The first rule, he says, is to (2)____ only what you truly love, not what others think is popular. No one can (3)____ that a young artist will become famous, so you should never buy a work just for the (4)____ you hope to make. He also tells me to look at a lot of (5)____ art by living painters, because some of it is also (6)____ of attention. Before buying, he always asks himself one simple (7)____: does this picture move me? If the answer is no, he walks (8)____. Over the years, his small collection has slowly (9)____ a fine reputation. Yet for him, the real (10)____ of collecting art is not money, but the joy each painting brings him every single day.', 140, 2, '[{"q":"1","answer":"C","options":["noise","price","advice","weather"],"explanation":"useful advice 有用的建议。"},{"q":"2","answer":"D","options":["sell","throw","hide","purchase"],"explanation":"purchase only what you love 只买所爱。"},{"q":"3","answer":"A","options":["guarantee","break","leave","lose"],"explanation":"guarantee that 保证。"},{"q":"4","answer":"B","options":["noise","money","song","weather"],"explanation":"the money you make 你赚的钱。"},{"q":"5","answer":"C","options":["broken","silent","contemporary","empty"],"explanation":"contemporary art 当代艺术。"},{"q":"6","answer":"D","options":["afraid","sorry","tired","worthy"],"explanation":"worthy of attention 值得关注。"},{"q":"7","answer":"A","options":["question","price","song","machine"],"explanation":"one simple question 一个简单问题。"},{"q":"8","answer":"B","options":["up","away","in","off"],"explanation":"walk away 走开。"},{"q":"9","answer":"C","options":["sold","lost","earned","broke"],"explanation":"earned a reputation 赢得名声。"},{"q":"10","answer":"D","options":["price","noise","error","value"],"explanation":"the real value 真正的价值。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U1', 'Becoming a Young Sculptor', 'Ever since I was small, my dream has been to become a (1)____ one day. I love to take a piece of soft clay and slowly (2)____ it into the shape of an animal. Unlike a flat painting, a sculpture exists in three (3)____, so you can walk around it and see it from every (4)____. My teacher says the hardest part is learning when to (5)____ adding clay and leave the work alone. At first I was not (6)____ with the results, and many of my early pieces broke. But I refused to give up, because every mistake (7)____ me something new. Little by little, my small clay figures began to look more (8)____, almost as if they could move. Last week, one of them won a prize at the school (9)____. That moment gave me the (10)____ to keep working towards my dream of becoming a real artist.', 150, 2, '[{"q":"1","answer":"A","options":["sculptor","driver","doctor","farmer"],"explanation":"become a sculptor 成为雕塑家。"},{"q":"2","answer":"B","options":["sell","shape","eat","throw"],"explanation":"shape it 把它塑形。"},{"q":"3","answer":"C","options":["minutes","metres","dimensions","colours"],"explanation":"three dimensions 三维。"},{"q":"4","answer":"D","options":["price","song","noise","side"],"explanation":"from every side 从各个角度。"},{"q":"5","answer":"A","options":["stop","begin","sell","lose"],"explanation":"when to stop 何时停下。"},{"q":"6","answer":"B","options":["afraid","happy","sorry","angry"],"explanation":"be happy with 对……满意(打散后位置变)。"},{"q":"7","answer":"C","options":["sold","lost","taught","broke"],"explanation":"taught me something 教会我。"},{"q":"8","answer":"D","options":["empty","silent","cheap","realistic"],"explanation":"look realistic 看起来逼真。"},{"q":"9","answer":"A","options":["exhibition","market","station","factory"],"explanation":"school exhibition 学校展览。"},{"q":"10","answer":"B","options":["noise","courage","price","error"],"explanation":"gave me the courage 给了我勇气。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U1', 'Talking about a Famous Painting', 'In class today we talked about one of the most famous Chinese (1)____ in the world. It shows the busy life along a river during an old (2)____. The teacher asked us to look (3)____ at the tiny figures: boats, shops, bridges, and crowds of ordinary people. She said the great (4)____ of the work is that it lets us see how people really lived long ago. One student asked how the artist could paint so many people so (5)____. The teacher explained that he must have watched the streets for years and remembered every (6)____. Although the painting is hundreds of years (7)____, the people in it still seem alive. By looking closely, we can almost (8)____ the noise of the market. The teacher told us that this is why the work is (9)____ as a treasure. For me, it was a chance to (10)____ how powerful a single painting can be.', 153, 2, '[{"q":"1","answer":"C","options":["machines","songs","paintings","markets"],"explanation":"Chinese paintings 中国画。"},{"q":"2","answer":"D","options":["price","noise","engine","festival"],"explanation":"an old festival 古老的节日。"},{"q":"3","answer":"A","options":["closely","away","down","loudly"],"explanation":"look closely 仔细看。"},{"q":"4","answer":"B","options":["price","value","noise","weather"],"explanation":"the great value 巨大的价值。"},{"q":"5","answer":"C","options":["loudly","sadly","precisely","quietly"],"explanation":"paint precisely 精确地画。"},{"q":"6","answer":"D","options":["price","song","machine","detail"],"explanation":"every detail 每个细节(打散后位置变)。"},{"q":"7","answer":"A","options":["old","wide","cheap","loud"],"explanation":"hundreds of years old 数百年之久。"},{"q":"8","answer":"B","options":["sell","hear","throw","lose"],"explanation":"almost hear 几乎能听见。"},{"q":"9","answer":"C","options":["sold","lost","regarded","broken"],"explanation":"regarded as a treasure 被视为珍宝。"},{"q":"10","answer":"D","options":["forget","waste","hide","realise"],"explanation":"realise how powerful 意识到多有力量。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·对话 Which Style Do You Like', '选择性必修三 U1 · dialogue', 3, 'Anna: Which period of Western art do you like most, Ben?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·短文 Ink Wash Animation', '选择性必修三 U1 · passage', 2, 'Today I''d like to talk about Chinese ink wash animation films.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·对话 Monet''s Garden', '选择性必修三 U1 · dialogue', 3, 'Guide: This room shows Monet''s famous garden at Giverny.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·短文 Museum Announcement', '选择性必修三 U1 · passage', 2, 'Welcome to the Museum of Fine Art''s newest exhibition.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·对话 Advice on Learning to Paint', '选择性必修三 U1 · dialogue', 3, 'Lily: I really want to learn to paint, but I don''t know how to begin.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·短文 What Is Modern Art', '选择性必修三 U1 · passage', 2, 'After Impressionism, artists began to ask a brave new question.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Introduce a Painting, an Artist or an Art Style(介绍一幅画/一位艺术家/一种艺术风格)', 'An Artwork I Love', '假设你叫李华,学校英语角要办一期''我最爱的艺术''专栏。请用英语写一篇约100词的短文,介绍你最喜爱的一幅画、一位艺术家或一种艺术风格,内容包括:① 它/他是谁、属于哪个时期或风格;② 这件作品(或风格)的主要特点;③ 你为什么喜欢它。注意:用不定式作表语点明主旨(如 The aim of this style is to … / My favourite hobby is …),行文连贯。', 'Suppose you are Li Hua. Your school English corner is running a column called ''The Art I Love''. Write a short passage (about 100 words) to introduce your favourite painting, artist, or art style, including: 1) who or what it is, and which period or style it belongs to; 2) the main features of the work or style; 3) why you like it. Try to use the infinitive as the predicative (e.g. The aim of this style is to …).', '["点明对象与时期/风格(This painting / artist / style belongs to …)","描述主要特点(Its main feature is … / The aim of this style is to …)","说明喜欢的理由(What I love most about it is …)","用不定式作表语、行文连贯、词汇地道"]'::jsonb, 70, 100, 'My favourite work of art is Monet''s painting Impression, Sunrise. It belongs to Impressionism, a style that emerged in France in the late 19th century. The aim of this style is to capture light, colour, and a single moment''s feeling, rather than to make a precise record of a scene. In the painting, a few soft brushstrokes turn the harbour at dawn into something warm and alive. What I love most about it is the way it shows the world as the painter truly felt it. Every time I look at it, my own wish is to see ordinary things with fresh eyes.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["It belongs to Impressionism, a style that emerged in France in the late 19th century.","The aim of this style is to capture light, colour, and a single moment''s feeling.","A few soft brushstrokes turn the harbour at dawn into something warm and alive.","What I love most about it is the way it shows the world as the painter truly felt it."]'::jsonb, '[{"wrong":"The aim of this style is capture light.","correct":"The aim of this style is to capture light.","note":"主语 aim 是抽象名词,be 后用不定式作表语,需 to。"},{"wrong":"It belong to Impressionism.","correct":"It belongs to Impressionism.","note":"主语第三人称单数,动词加 s。"},{"wrong":"My wish is seeing things with fresh eyes.","correct":"My wish is to see things with fresh eyes.","note":"wish 后作表语表''要做的事'',用不定式而非动名词。"}]'::jsonb, '【介绍艺术作品结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective3', 'U1', '{"title":"不定式作表语(The Infinitive as the Predicative)速查","intro":"当主语是 advice/dream/aim/plan/job/wish/question/problem 等抽象名词时,系动词 be 后常用动词不定式(to do)或''疑问词+不定式''作表语,说明主语的具体内容。判断口诀:主语是抽象名词 + be + 要做的事 → to do。","table":{"headers":["类型","结构 / 例句"],"rows":[["be + to do","My advice is to start early. / Her dream is to become an artist."],["疑问词 + to do","The question is what to paint. / The problem is how to begin."],["be to do(计划/职责/将来)","The plan is to hold an exhibition. / The task is to repair it."],["doing(动名词表语·对照)","His hobby is painting.(说明''是什么活动'',非计划/职责)"]]},"specialRules":[{"rule":"主语为 advice/dream/aim/wish/plan 等抽象名词 → be 后多用 to do 作表语","mark":"My wish is to raise him well."},{"rule":"内容是''做什么/怎么做/是否做''的问题 → 用''疑问词(what/how/where/whether)+ to do''","mark":"The problem is how to begin."},{"rule":"plan/task/duty/aim 表''计划·职责·将来'' → to do;hobby/interest/job 指''日常活动'' → doing","mark":"plan is to hold √ / hobby is painting √"},{"rule":"不定式表语 ≠ 动名词表语:看主语含义,不是随意互换","mark":"aim is to win / pleasure is walking"}],"why":["不定式带有''将要/目的''的意味,所以 advice/dream/plan/aim 等''要去实现的内容''用 to do;动名词强调''正在/经常进行的活动本身'',所以 hobby/interest 等用 doing。"],"gaokaoPoints":["be 后填非谓语:主语是 aim/plan/wish 等抽象名词时选 to do,而非 doing/done/do;语法填空与改错高频。","''疑问词 + to do''作表语:The question is what/how/where/whether to do …,注意疑问词后直接接不定式。"],"examVsReal":[{"exam":"My advice is to start early.(考试/书面)","real":"I''d say: start early.","note":"考试用不定式作表语点明主旨;口语常直接用祈使句或省略"},{"exam":"The plan is to hold an exhibition.(考试)","real":"We''re going to hold an exhibition.","note":"考试爱用''主语+be+to do''表语句式;口语更常用 be going to"}]}'::jsonb);
